choices.executeEval:
const prey = FqCardEngineModule.cst.currentTargets[0];
const beasts = FqCardEngineModule.cond.minionTokensOnScene("beast");
if (prey && beasts.length) {
const preyDoc = prey.document ?? prey;
const distance = t => Math.hypot(t.x - preyDoc.x, t.y - preyDoc.y);
const closest = beasts.sort((a, b) => distance(a) - distance(b))[0];
FqCardEngineModule.wpn.triggerFirstEquippedWeapon(closest.actor, "@wpnM");
}
